export const BODY: string = "\n<p>إضافة خلفية إلى صورة عمل قصير عندما تعرف الخطوات. ترفع صورة أو قصاصة شفافة وتختار خلفية وتحدد شكل الإطار وتنزّل الصورة المكتملة. يمر هذا الدليل بكل خطوة بالترتيب.</p>\n<p>قبل أن تبدأ تحتاج إلى شيء واحد فقط: الصورة الرئيسية. قد تكون صورة عادية أو قصاصة PNG شفافة أو شعارًا أو لقطة شاشة. وإذا كانت صورتك ما زالت تحمل خلفية أصلية فوضوية، فأزلها أولًا لتحصل على قصاصة نظيفة.</p>\n<p><a href=\"/ar/idafa-khalfiyya-ila-as-sura/\">أداة إضافة خلفية إلى صورة</a> تقوم بالعمل في متصفحك. لا شيء يُرفع إلى خادم ولا حساب والتصدير مجاني. اتبع الخطوات أدناه وستحصل على صورة مكتملة في دقائق معدودة.</p>\n<h2 id=\"step-1-upload-your-image\">الخطوة 1: ارفع صورتك</h2>\n<p>افتح الأداة واسحب صورتك إلى منطقة الرفع، أو انقر لاختيار ملف من جهازك. ويمكنك أيضًا لصق صورة مباشرة من الحافظة بـCtrl وV، وهذا مفيد للقطات الشاشة.</p>\n<p>تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 ميغابايت. ومعظم الصور والقصاصات أقل بكثير من هذا الحد. وبمجرد تحميل الصورة، تظهر فوق الخلفية الافتراضية مع أدوات التأطير بجانبها.</p>\n<h2 id=\"step-2-pick-a-background-mode\">الخطوة 2: اختر وضع الخلفية</h2>\n<p>اختر أحد الأوضاع الثلاثة: لون واحد أو تدرج أو صورة مموّهة. اللون الواحد يملأ اللوحة بلون واحد مسطح ويناسب صور المنتجات والشعارات وكل ما يتطلب أن تهيمن الصورة الرئيسية.</p>\n<p>التدرج يمزج لونين عبر اللوحة بزاوية، ويناسب منشورات التواصل وإطارات القصص والرسوم الترويجية حيث يجب أن تضيف الخلفية طاقة. أما الصورة المموّهة فتملأ اللوحة بنسخة مموّهة من صورتك، وتناسب الصور التي لا يطابق شكلها الإطار.</p>\n<h2 id=\"step-3-choose-a-color-or-colors\">الخطوة 3: اختر لونًا أو ألوانًا</h2>\n<p>في وضع اللون الواحد، اختر من العينات السريعة أو افتح منتقي الألوان لدرجة دقيقة. الأبيض هو المعيار للإعلانات، ولون العلامة يناسب حملة، ودرجة داكنة تناسب منتجًا فاخرًا.</p>\n<p>في وضع التدرج، اختر لونين وزاوية. الزاوية القطرية تبدو ديناميكية، والعمودية تبدو هادئة، والأفقية تبدو واسعة. وابدأ بألوان قريبة لمزج ناعم. وفي وضع الصورة المموّهة لا لون للاختيار، فالخلفية تأتي من الصورة نفسها؛ واضبط بدلًا من ذلك نصف قطر التمويه.</p>\n<h2 id=\"step-4-set-the-canvas-ratio\">الخطوة 4: حدد نسبة اللوحة</h2>\n<p>اختر شكل اللوحة حسب المكان الذي ستُنشر فيه الصورة. المربع يناسب الخلاصات والإعلانات والصور المصغرة. والشكل العريض 16:9 يناسب اللافتات وصور الفيديو المصغرة. والشكل العمودي 4:5 يناسب الخلاصات التي تكافئ الصور الطويلة.</p>\n<p>فكر في أين ستقص المنصة الصورة. تطبيقات التواصل تقص المعاينات إلى أشكالها الخاصة، وصورة رئيسية قرب الحافة قد تُقص. وأبقِ الجزء المهم متمركزًا. وإذا لم تعرف أين ستُستخدم الصورة، فاختر المربع: إنه الشكل الأكثر مرونة.</p>\n<h2 id=\"step-5-scale-the-foreground\">الخطوة 5: اضبط حجم الصورة الرئيسية</h2>\n<p>استخدم التحكم في مقياس الصورة لتحديد حجم ظهور الصورة الرئيسية في الإطار. مقياس كبير يملأ اللوحة ويجعل الموضوع بطلًا. ومقياس صغير يترك هوامش واسعة ويعطي إحساسًا بالهدوء.</p>\n<p>اترك هواء حول الموضوع. منتج ملتصق بحافة الإطار يبدو ضيقًا، بينما منتج طافٍ في لوحة كبيرة فارغة يبدو ضائعًا. وعندما يختلف شكل اللوحة عن شكل الصورة، يقوم المقياس بعمل التأطير: صورة طويلة في لوحة مربعة تحتاج مقياسًا أصغر لتناسب.</p>\n<h2 id=\"step-6-add-roundness-and-shadow\">الخطوة 6: أضف تدويرًا وظلًا</h2>\n<p>التدوير ينعّم زوايا صورة رئيسية مستطيلة. تدوير خفيف يعطي إحساسًا بالبطاقة ويناسب منشورات التواصل ولقطات التطبيقات. وتدوير قوي يحوّل الصورة إلى شكل دائري تقريبًا.</p>\n<p>ولقصاصة PNG شفافة، يكون للتدوير أثر قليل، لأن الزوايا محددة أصلًا بالتصميم نفسه. أما الظل فيجعل الصورة الرئيسية ترتفع عن الخلفية ويضيف عمقًا. ويعمل أفضل مع القصاصات الشفافة والشعارات، حيث يتبع الظل شكل الجسم. وأبقِ كلا التأثيرين خفيفين.</p>\n<h2 id=\"step-7-check-the-preview\">الخطوة 7: راجع المعاينة</h2>\n<p>انظر إلى المعاينة الكاملة قبل التصدير. تحقق من أن الصورة الرئيسية متمركزة والهوامش متساوية ولون الخلفية أو تدرجها يبدو كما تخيلت. ونظرة سريعة الآن تكتشف مشكلة تأطير قبل أن تكلفك إعادة تصدير.</p>\n<p>راجع حواف الصورة الرئيسية. قصاصة بحافة خشنة أو هالة متبقية من الخلفية القديمة تظهر بوضوح مقابل لون واحد. وإذا بدت الحافة غير منتظمة، ارجع ونظّف القصاصة أولًا. وانظر إلى الصورة على هاتفك إن استطعت، فخلفية تبدو خفيفة على شاشة مكتب قد تبدو قوية على شاشة هاتف.</p>\n<h2 id=\"step-8-export-and-download\">الخطوة 8: صدّر ونزّل</h2>\n<p>اختر صيغة التصدير. JPG يناسب الصور وأي صورة يهم فيها حجم الملف الصغير، مثل منشور اجتماعي أو لافتة موقع. وPNG يناسب الصور ذات النص الحاد والألوان المسطحة.</p>\n<p>انقر تنزيل وستُحفظ الصورة المكتملة على جهازك. واسم الملف يعكس إعدادات الخلفية، فتستطيع تمييز النسخ عندما تصدّر عدة نسخ. وافتح الملف المنزّل وانظر إليه مرة أخرى: راجع الحجم والصيغة والمظهر بالحجم الذي سيُنشر به.</p>\n<h2 id=\"step-9-use-the-image\">الخطوة 9: استخدم الصورة</h2>\n<p>ارفع الصورة المكتملة إلى وجهتها: إعلان متجر أو منشور اجتماعي أو عرض تقديمي أو لافتة موقع. واستخدم الملف كما هو، لأن الخلفية والتأطير والصيغة جاهزة.</p>\n<p>لإعلان متجر، أرفق الصورة بالعنوان ووصف المنتج المناسبين. صورة بخلفية نظيفة وعنوان واضح تحوّل أفضل من صورة مزدحمة بعنوان ضعيف. ولوسائل التواصل، انشر الصورة بالنسبة التي تفضلها المنصة وأضف النص منفصلًا. واحفظ الملف المصدّر كنسختك الرئيسية لتلك الوجهة.</p>\n<h2 id=\"backgrounds-for-different-photo-types\">خلفيات لأنواع صور مختلفة</h2>\n<p>البورتريه يحتاج خلفية تُبقي الوجه بطلًا. لون واحد ناعم أو خلفية مموّهة لطيفة تعمل جيدًا، لأن كليهما يبقى هادئًا خلف الشخص. وتجنب التدرجات القوية خلف الوجوه.</p>\n<p>صور المنتجات تحتاج المعاملة المعاكسة: يجب أن تكون الخلفية محايدة قدر الإمكان ليحكم المشترون على المنتج لا على المشهد. الأبيض هو المعيار، والرمادي الفاتح بديل جيد. وتصوير الطعام يستفيد من خلفيات دافئة وطبيعية: كريمي ناعم أو درجة خشبية شاحبة أو مشهد مطبخ مموّه يجعل الطبق يبدو شهيًا.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق للخلفيات</h2>\n<p>ارفع الصورة الرئيسية، واختر لونًا واحدًا أو تدرجًا أو صورة مموّهة، واختر اللون أو التمويه، وحدد نسبة اللوحة للوجهة، واضبط حجم الصورة الرئيسية مع هواء للتنفس، وأضف تدويرًا وظلًا خفيفين، وراجع المعاينة.</p>\n<p>صدّر JPG للصور وPNG للنص الحاد أو الشفافية، ثم راجع التنزيل بالحجم الذي سيُرى به. وإذا بدت حافة قصاصة خشنة، نظّف القصاصة أولًا وصدّر مجددًا.</p>\n<p>للدليل الكامل لكل وضع، اقرأ <a href=\"/ar/blog/dalil-idafa-khalfiyya-ila-as-suwar/\">إضافة خلفية إلى الصور: الدليل الكامل</a>، ولنصائح منتجات محددة اقرأ <a href=\"/ar/blog/khalfiyyat-suwar-al-muntajat/\">خلفيات صور المنتجات: الألوان والسياق</a>. وابدأ الآن مع <a href=\"/ar/idafa-khalfiyya-ila-as-sura/\">أداة إضافة خلفية إلى صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يجب أن أزيل الخلفية القديمة قبل إضافة واحدة جديدة؟","answer":"لأنظف نتيجة، نعم. إذا أضفت خلفية إلى صورة ما زالت تحمل خلفيتها الأصلية، فالخلفية القديمة تبقى ظاهرة داخل الإطار. أزلها أولًا بمزيل خلفية ثم ضع القصاصة الشفافة فوق الخلفية الجديدة."},{"question":"ما أفضل خلفية لإعلان متجر عبر الإنترنت؟","answer":"خلفية بيضاء واحدة هي المعيار في المتاجر، لأنها تُبقي المنتج البطل الوحيد وتتناسب مع شبكة الصور المصغرة. ولمتجرك الخاص أو خلاصتك الاجتماعية، لون علامة متسق يعمل جيدًا أيضًا."},{"question":"هل يمكنني استخدام صورة التقطتها بهاتفي؟","answer":"نعم، تقبل الأداة ملفات JPG وPNG وWebP وHEIC من الهواتف حتى 20 ميغابايت لكل منها. ويمكنك أيضًا لصق لقطة شاشة من الحافظة. ولأفضل نتيجة، استخدم أعلى نسخة دقة لديك."},{"question":"كيف أمنع منتجي من لمس حواف الإطار؟","answer":"استخدم التحكم في مقياس الصورة لتصغير الصورة الرئيسية حتى يكون هناك هامش متساوٍ في كل الجوانب. قليل من الهواء يجعل الصورة تبدو مقصودة وفاخرة، بينما منتج ملتصق بالحافة يبدو ضيقًا."},{"question":"هل ستعمل الخلفية التي أضيفها في كل منصات التواصل؟","answer":"الخلفية نفسها تعمل في أي مكان، لكن شكل اللوحة مهم. المربع يناسب شبكات الخلاصة، و4:5 يناسب الخلاصات عند التمرير، و16:9 يناسب اللافتات والصور المصغرة. وصدّر بالنسبة التي تفضلها كل منصة."},{"question":"هل يمكنني تغيير الخلفية مجددًا بعد التنزيل؟","answer":"نعم، فملف صورتك الرئيسية الأصلي يبقى سليمًا، فارجع إلى الأداة وارفعه مجددًا واختر خلفية أخرى. ومن الأفضل إعادة التصدير من الأصل بدل تحرير الصورة المكتملة، التي تفقد جودة في كل جولة."}];
